//! Compares the seed correction after the segmentation
//! (`dca_algo::seed_check`) with the Python plugin.
//!
//! `fixtures/seed_check.json` is generated by `fixtures/gen_seed_check.py`
//! from the plugin's own `segmentation.py` (python3 + numpy, no Blender), on
//! synthetic crown spans: the numbering from the widths
//! (`renumber_spans`), the corrections of a report (`plan_corrections`,
//! `report_issues`), the seed of a crown and the face labels.

use std::collections::BTreeMap;
use std::path::PathBuf;

use dca_algo::anatomy::Arch;
use dca_algo::seed_check::{self, Action, Report, Span, Weak};
use glam::DVec3;
use serde_json::Value;

fn fixture() -> Value {
    let path = PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures/seed_check.json");
    serde_json::from_str(&std::fs::read_to_string(path).unwrap()).unwrap()
}

fn spans(v: &Value) -> BTreeMap<u16, Span> {
    v.as_object()
        .unwrap()
        .iter()
        .map(|(k, s)| {
            (
                k.parse().unwrap(),
                (s[0].as_f64().unwrap(), s[1].as_f64().unwrap()),
            )
        })
        .collect()
}

fn ints(v: &Value) -> Vec<u16> {
    v.as_array()
        .unwrap()
        .iter()
        .map(|x| x.as_u64().unwrap() as u16)
        .collect()
}

fn arch(c: &Value) -> Arch {
    if c["arch"] == "upper" {
        Arch::Upper
    } else {
        Arch::Lower
    }
}

#[test]
fn the_numbers_from_the_widths_are_the_plugins() {
    let f = fixture();
    for (k, c) in f["cases"].as_array().unwrap().iter().enumerate() {
        let (new, notes) = seed_check::renumber_spans(
            &spans(&c["spans"]),
            arch(c),
            c["third"].as_bool().unwrap(),
            &ints(&c["missing"]),
        );
        let want: BTreeMap<u16, u16> = c["renumber"]
            .as_object()
            .unwrap()
            .iter()
            .map(|(k, v)| (k.parse().unwrap(), v.as_u64().unwrap() as u16))
            .collect();
        assert_eq!(new, want, "case {k}");
        assert_eq!(notes.len() as u64, c["notes"].as_u64().unwrap(), "case {k}");
    }
}

#[test]
fn the_corrections_of_a_report_are_the_plugins() {
    let f = fixture();
    for (k, c) in f["cases"].as_array().unwrap().iter().enumerate() {
        let sp = spans(&c["report"]["spans"]);
        let weak = c["report"]["weak"]
            .as_array()
            .unwrap()
            .iter()
            .map(|w| Weak {
                a: w[0].as_u64().unwrap() as u16,
                b: w[1].as_u64().unwrap() as u16,
                len_mm: w[2].as_f64().unwrap(),
                fold: w[3].as_f64().unwrap(),
                s: (w[4].as_f64().unwrap(), w[5].as_f64().unwrap()),
            })
            .collect();
        let molar = seed_check::arch_widths(arch(c))
            .into_iter()
            .fold(0.0, f64::max);
        let rep = Report {
            slivers: ints(&c["slivers"]),
            wide: ints(&c["wide"]),
            spans: sp,
            weak,
            molar,
        };
        // the sliver and wide lists are the check's thresholds
        let slivers: Vec<u16> = rep
            .spans
            .iter()
            .filter(|(_, (a, b))| b - a < seed_check::SLIVER_MM)
            .map(|(f, _)| *f)
            .collect();
        assert_eq!(slivers, rep.slivers, "case {k}");
        assert_eq!(
            seed_check::report_issues(&rep).len() as u64,
            c["issues"].as_u64().unwrap(),
            "case {k}"
        );
        let want: Vec<Action> = c["actions"]
            .as_array()
            .unwrap()
            .iter()
            .map(|a| {
                let n = |i: usize| a[i].as_u64().unwrap() as u16;
                match a[0].as_str().unwrap() {
                    "drop" => Action::Drop { fdi: n(1) },
                    "merge" => Action::Merge {
                        keep: n(1),
                        drop: n(2),
                    },
                    _ => Action::Split {
                        fdi: n(1),
                        cut: a[2].as_f64().unwrap(),
                    },
                }
            })
            .collect();
        assert_eq!(seed_check::plan_corrections(&rep), want, "case {k}");
    }
}

#[test]
fn the_seed_of_a_crown_and_the_face_labels_are_the_plugins() {
    let f = fixture();
    let p: Vec<DVec3> = f["crown_seed"]["points"]
        .as_array()
        .unwrap()
        .iter()
        .map(|q| {
            DVec3::new(
                q[0].as_f64().unwrap(),
                q[1].as_f64().unwrap(),
                q[2].as_f64().unwrap(),
            )
        })
        .collect();
    let s = &f["crown_seed"]["seed"];
    let want = DVec3::new(
        s[0].as_f64().unwrap(),
        s[1].as_f64().unwrap(),
        s[2].as_f64().unwrap(),
    );
    assert_eq!(seed_check::crown_seed(&p), Some(want));
    let t: Vec<[u32; 3]> = f["face_labels"]["tris"]
        .as_array()
        .unwrap()
        .iter()
        .map(|x| [0, 1, 2].map(|i| x[i].as_u64().unwrap() as u32))
        .collect();
    let labels = ints(&f["face_labels"]["labels"]);
    assert_eq!(
        seed_check::face_labels(&t, &labels),
        ints(&f["face_labels"]["faces"])
    );
}
